transforms.code:
if value is None or not value.has_key('assetPath') or value['assetPath'] is None: return []
assetPath = value['assetPath']	

counters = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getCounter({'assetPath': assetPath + '%'}))
tagPath = '[Kanoa]' + assetPath.replace("\\", '/')

tagSearchList = [
					{'tagPath': tagPath, 'filters': {"tagType":"UdtInstance", "typeId": "[Kanoa]_types_/Kanoa/assetOEE", "recursive":True}, 'tagNameList': ['Configuration/infeedCounterId', 'Configuration/outfeedCounterId', 'Configuration/wasteCounterId']},
					{'tagPath': tagPath, 'filters': {"tagType":"UdtInstance", "typeId": "[Kanoa]_types_/Kanoa/counter", "recursive":True}, 'tagNameList': []},
					{'tagPath': tagPath, 'filters': {"tagType":"UdtInstance", "typeId": "[Kanoa]_types_/Kanoa/generalCounter", "recursive":True}, 'tagNameList': []},
					{'tagPath': tagPath, 'filters': {"tagType":"UdtInstance", "typeId": "[Kanoa]_types_/Kanoa/counters/counter", "recursive":True}, 'tagNameList': ['counterId']}
				]

tagInfoList = []
for ts in tagSearchList:
	results = system.tag.browse(path = ts['tagPath'], filter = ts['filters']).results
	for result in results:
		path = str(result['fullPath'])
		for tagName in ts['tagNameList']:
			parentPath = path.rsplit('/', len(tagName.split("/"))-1)[0]
			tagInfoList.append({'tagName': tagName, 'tagPath': path + '/' + tagName, 'parentPath': parentPath, 'udtType': ts['filters']['typeId']})

tagValues = system.tag.readBlocking([item['tagPath'] for item in tagInfoList])

tags = {}
for i, tagValue in enumerate(tagValues):
	tags[tagValue.value] = tagInfoList[i]

for counter in counters:
	if tags.has_key(counter['counterId']):
		tagInfo = tags[counter['counterId']]
		tagName = tagInfo['tagName']
		tagPath = tagInfo['tagPath'].rsplit("/", len(tagName.split("/")))[0] if tagInfo['tagPath'] else None
		udtType = tagInfo['udtType']
	else: 
		tagPath, udtType = None, None

	counter['tagPath'] = tagPath
	counter['udtType'] = udtType

return counters

security = value['security']
canCreate = False
canEdit = False

counters = value['data'] or []
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureAssets']['enabled']: 
		canCreate = True
		canEdit = True if len(counters) > 0 and counters[0]['udtType'] != '[Kanoa]_types_/Kanoa/assetOEE' else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

config.script:
modeAssetLinkId = self.props.data[event.row].modeAssetLinkId
if modeAssetLinkId is None: return

if self.view.custom.assetModes.userAction['canUpdate']:
	if event.column == 'linkEnabled':
		retVal = system.kanoa.asset.enableModeAssetLink(modeAssetLinkId, int(event.value))
		if retVal: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Asset Mode link has been updated'})
		else: system.perspective.sendMessage('showFailerToast', {'message': 'Unable to update Asset Mode link'})
	if event.column == 'autoSchedule':
		retVal, msg = system.kanoa.asset.updateAssetModeField(modeAssetLinkId, 'autoSchedule', event.value, self.view.custom.security.userId)
		if msg is not None: system.perspective.sendMessage('showFailerToast', {'message': 'Unable to update Asset Mode %s setting. %s'%(event.column, msg)})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Asset Mode %s setting has been updated'%event.column})
	elif event.column == 'modeCode':
		retVal, msg = system.kanoa.asset.setAssetModeCode(modeAssetLinkId, int(event.value))
		if msg is not None: system.perspective.sendMessage('showFailerToast', {'message': msg})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Asset Mode %s setting has been updated'%event.column})
	else: system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing.')	
else: system.perspective.sendMessage('showFailerToast', 'No permissions to update modes.')

self.view.refreshBinding("custom.assetModes.data")

return

